package com.opencrm.order.fulfillment;
import com.opencrm.common.order.AcceptedOrderSnapshot;
import com.opencrm.common.order.AcceptedOrderSnapshot.Line;
import com.opencrm.order.dto.OrderDtos.*;
import com.opencrm.order.domain.OrderProblem;
import com.opencrm.order.security.OrderAccess;
import com.opencrm.order.service.OrderService;
import com.opencrm.order.execution.ExecutionService;
import org.junit.jupiter.api.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.datasource.*;
import org.flywaydb.core.Flyway;
import org.testcontainers.containers.PostgreSQLContainer;
import org.testcontainers.junit.jupiter.*;
import tools.jackson.databind.json.JsonMapper;
import java.time.*;
import java.util.*;
import static org.mockito.Mockito.*;
import static org.junit.jupiter.api.Assertions.*;
@Testcontainers
@Tag("integration")
class FulfillmentIntegrationTest {
 @Container static PostgreSQLContainer<?> postgres=new PostgreSQLContainer<>("postgres:16-alpine");
 JdbcTemplate db;OrderService orders;ExecutionService execution;EvidenceService evidence;OrderAccess access;JsonMapper json=JsonMapper.builder().build();
 @BeforeAll static void migrate(){Flyway.configure().dataSource(postgres.getJdbcUrl(),postgres.getUsername(),postgres.getPassword()).schemas("order_management").defaultSchema("order_management").load().migrate();}
 @BeforeEach void setup(){var ds=new DriverManagerDataSource(postgres.getJdbcUrl()+"&currentSchema=order_management",postgres.getUsername(),postgres.getPassword());db=new JdbcTemplate(ds);db.execute("TRUNCATE snapshot_inbox,outbox_events,execution_inbox CASCADE");var manager=new DataSourceTransactionManager(ds);access=mock(OrderAccess.class);when(access.actor()).thenReturn("operator");when(access.scopeId()).thenReturn("pilot");when(access.customerIds()).thenReturn(Set.of("customer"));orders=new OrderService(db,manager,json,access,true,"pilot");execution=new ExecutionService(db,manager,json,access,true,"pilot");evidence=new EvidenceService(db,manager,json,access,execution,"pilot");}
 View order(String type){var line=new Line("line","product","Widget",type,"ONE_TIME",10,"EA","10","0","0","100","ONE_TIME",null,null);var s=new AcceptedOrderSnapshot(1,"snapshot","00000000-0000-0000-0000-000000000001","Q-1",1,"pilot","customer",Instant.parse("2026-09-01T00:00:00Z"),"USD","100","0","0","100","address","approval","tax","config",List.of(line));String payload=json.writeValueAsString(s);orders.acceptTrustedSnapshot(payload,OrderService.hash(payload));var v=orders.fromQuote(new FromQuote("snapshot",s.quoteId(),1),"convert");return orders.submit(v.id(),new Command(0,"go","submit"));}
 EvidenceCommand command(View o,String kind,int qty,String reference,String allocation,String shipment,Instant at,Instant expiry){if("ALLOCATION".equals(kind) && expiry==null)expiry=Instant.now().plusSeconds(3600);return new EvidenceCommand(orders.get(o.id()).version(),"op-"+reference,"verified by operator",o.lines().getFirst().id(),kind,qty,reference,at,allocation,shipment,expiry);}
 EvidenceReceipt record(View o,String kind,int qty,String ref,String allocation,String shipment){return evidence.record(o.id(),command(o,kind,qty,ref,allocation,shipment,Instant.now(),null));}
 @Test void allocationAndPartialShipmentUseExactQuantities(){var o=order("PHYSICAL");record(o,"ALLOCATION",4,"allocation",null,null);assertEquals(4,orders.get(o.id()).lines().getFirst().allocated());record(o,"SHIPMENT",4,"shipment","allocation",null);var line=orders.get(o.id()).lines().getFirst();assertEquals(4,line.shipped());assertEquals(6,line.remaining());assertEquals(0,line.allocated());}
 @Test void repeatedEvidenceDoesNotIncrementQuantity(){var o=order("PHYSICAL");var command=command(o,"ALLOCATION",4,"allocation",null,null,Instant.now(),null);evidence.record(o.id(),command);evidence.record(o.id(),command);assertEquals(4,orders.get(o.id()).lines().getFirst().allocated());assertEquals(1,db.queryForObject("SELECT count(*) FROM fulfillment_evidence",Integer.class));}

 @Test void partialShipmentReplayAndCancellationConserveQuantity(){var o=order("PHYSICAL");record(o,"ALLOCATION",4,"allocation",null,null);var shipment=command(o,"SHIPMENT",4,"shipment","allocation",null,Instant.now(),null);evidence.record(o.id(),shipment);evidence.record(o.id(),shipment);var updated=orders.get(o.id());updated=orders.cancel(o.id(),new Cancellation(updated.version(),"cancel unallocated remainder","cancel",o.lines().getFirst().id(),2));var line=updated.lines().getFirst();assertEquals(4,line.shipped());assertEquals(2,line.cancelled());assertEquals(4,line.remaining());}
 @Test void pendingDeliveryIsRetainedThenAppliedAfterShipment(){var o=order("PHYSICAL");Instant now=Instant.now();record(o,"ALLOCATION",4,"allocation",null,null);var delivery=command(o,"DELIVERY",4,"delivery",null,"shipment",now.plusSeconds(2),null);assertEquals("PENDING",evidence.record(o.id(),delivery).status());assertEquals("IN_PROGRESS",orders.get(o.id()).status());assertEquals(0,orders.get(o.id()).lines().getFirst().delivered());var shipment=command(o,"SHIPMENT",4,"shipment","allocation",null,now.plusSeconds(1),null);evidence.record(o.id(),shipment);assertEquals(4,orders.get(o.id()).lines().getFirst().delivered());assertEquals("APPLIED",evidence.record(o.id(),delivery).status());assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM order_exceptions WHERE category='PENDING_DELIVERY' AND status='OPEN'",Integer.class));}
 @Test void sameExternalReferenceWithNewOperationKeyNeverCountsTwice(){var o=order("PHYSICAL");var first=command(o,"ALLOCATION",4,"allocation",null,null,Instant.now(),null);var result=evidence.record(o.id(),first);var second=new EvidenceCommand(result.version(),"second-key","same observed event",first.lineId(),first.kind(),first.quantity(),first.externalReference(),first.occurredAt(),null,null,first.expiresAt());assertEquals(result.evidenceId(),evidence.record(o.id(),second).evidenceId());assertEquals(4,orders.get(o.id()).lines().getFirst().allocated());assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM fulfillment_evidence",Integer.class));}
 @Test void contradictoryReferenceIsPreservedAndNotApplied(){var o=order("PHYSICAL");var first=command(o,"ALLOCATION",4,"allocation",null,null,Instant.now(),null);evidence.record(o.id(),first);var changed=new EvidenceCommand(orders.get(o.id()).version(),"changed","different claimed quantity",first.lineId(),first.kind(),5,first.externalReference(),first.occurredAt(),null,null,first.expiresAt());assertEquals("CONFLICT",evidence.record(o.id(),changed).status());assertEquals(4,orders.get(o.id()).lines().getFirst().allocated());assertEquals(2,evidence.ledger(o.id()).size());assertEquals(1,db.queryForObject("SELECT COUNT(*) FROM order_exceptions WHERE category='CONTRADICTORY_EVIDENCE'",Integer.class));}
 @Test void releasedAllocationReopensReadiness(){var o=order("PHYSICAL");record(o,"ALLOCATION",10,"allocation",null,null);record(o,"RELEASE",6,"release","allocation",null);assertEquals(4,orders.get(o.id()).lines().getFirst().allocated());assertEquals("WAITING_EXTERNAL",db.queryForObject("SELECT status FROM order_tasks WHERE order_id=? AND kind='ALLOCATION'",String.class,o.id()));}
 @Test void expiryRequiresManualReleaseAndCannotAuthorizeShipment(){var o=order("PHYSICAL");var at=Instant.now().minusSeconds(10);var alloc=command(o,"ALLOCATION",4,"allocation",null,null,at,Instant.now().plusSeconds(60));evidence.record(o.id(),alloc);db.update("UPDATE allocation_lots SET expires_at=clock_timestamp()-interval '1 second'");evidence.detectExpiredAllocations(10);assertEquals(4,orders.get(o.id()).lines().getFirst().allocated());assertEquals("CONFLICT",record(o,"SHIPMENT",4,"expired-shipment","allocation",null).status());assertEquals(0,orders.get(o.id()).lines().getFirst().shipped());record(o,"RELEASE",4,"release","allocation",null);assertEquals(0,orders.get(o.id()).lines().getFirst().allocated());assertEquals(0,db.queryForObject("SELECT count(*) FROM order_exceptions WHERE category='ALLOCATION_EXPIRED' AND status='OPEN'",Integer.class));}
 @Test void serviceAndDigitalProofCompleteOnlyTheirMatchingTask(){var o=order("SERVICE");record(o,"SERVICE",10,"service-proof",null,null);assertEquals(0,orders.get(o.id()).lines().getFirst().remaining());assertEquals("READY",db.queryForObject("SELECT status FROM order_tasks WHERE order_id=? AND kind='FINANCE_ACK'",String.class,o.id()));assertEquals("IN_PROGRESS",orders.get(o.id()).status());assertEquals(422,assertThrows(OrderProblem.class,()->record(o,"PROVISION",1,"wrong-kind",null,null)).status());}
 @Test void digitalProvisioningRequiresRealEvidence(){var o=order("DIGITAL");record(o,"PROVISION",10,"provider-completion",null,null);assertEquals(0,orders.get(o.id()).lines().getFirst().remaining());assertEquals(0,orders.get(o.id()).lines().getFirst().shipped());assertEquals("SUCCESS",db.queryForObject("SELECT status FROM order_tasks WHERE order_id=? AND kind='PROVISION'",String.class,o.id()));}
 @Test void unauthorizedEvidenceHasNoSideEffects(){var o=order("PHYSICAL");doThrow(new org.springframework.security.access.AccessDeniedException("denied")).when(access).require("oms:evidence","pilot","customer");assertThrows(org.springframework.security.access.AccessDeniedException.class,()->record(o,"ALLOCATION",4,"allocation",null,null));assertEquals(0,db.queryForObject("SELECT count(*) FROM fulfillment_evidence",Integer.class));assertEquals(0,orders.get(o.id()).lines().getFirst().allocated());}
 @Test void operatorEvidenceCannotBeChangedOrDeleted(){var o=order("PHYSICAL");record(o,"ALLOCATION",4,"allocation",null,null);assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE fulfillment_evidence SET quantity=9"));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("DELETE FROM fulfillment_evidence"));}

 @Test void firstPendingFactClosesSourceReplacementWindow(){var o=order("PHYSICAL");assertEquals("SUBMITTED",orders.get(o.id()).status());record(o,"DELIVERY",4,"early-delivery",null,"unseen-shipment");assertEquals("IN_PROGRESS",orders.get(o.id()).status());assertEquals(0,orders.get(o.id()).lines().getFirst().delivered());}

 @Test void fullPhysicalEvidenceReleasesFinanceButDoesNotInventAcknowledgment(){var o=order("PHYSICAL");record(o,"ALLOCATION",10,"allocation",null,null);record(o,"SHIPMENT",10,"shipment","allocation",null);record(o,"DELIVERY",10,"delivery",null,"shipment");assertEquals(10,orders.get(o.id()).lines().getFirst().delivered());assertEquals("READY",db.queryForObject("SELECT status FROM order_tasks WHERE order_id=? AND kind='FINANCE_ACK'",String.class,o.id()));assertEquals("IN_PROGRESS",orders.get(o.id()).status());assertEquals("PENDING",orders.get(o.id()).financeStatus());}
 @Test void cancellationOfAllRemainderCompletesOnlyAlreadyEvidencedPhases(){var o=order("PHYSICAL");record(o,"ALLOCATION",4,"allocation",null,null);record(o,"SHIPMENT",4,"shipment","allocation",null);orders.cancel(o.id(),new Cancellation(orders.get(o.id()).version(),"cancel remaining","cancel",o.lines().getFirst().id(),6));assertEquals("SUCCESS",db.queryForObject("SELECT status FROM order_tasks WHERE order_id=? AND kind='SHIPMENT'",String.class,o.id()));record(o,"DELIVERY",4,"delivery",null,"shipment");assertEquals("READY",db.queryForObject("SELECT status FROM order_tasks WHERE order_id=? AND kind='FINANCE_ACK'",String.class,o.id()));}
 @Test void competingCancellationAndAllocationHaveOneVersionWinner() throws Exception {var o=order("PHYSICAL");record(o,"ALLOCATION",4,"allocation",null,null);record(o,"SHIPMENT",4,"shipment","allocation",null);long version=orders.get(o.id()).version();var alloc=new EvidenceCommand(version,"new-alloc","verified",o.lines().getFirst().id(),"ALLOCATION",6,"new-allocation",Instant.now(),null,null,Instant.now().plusSeconds(3600));try(var pool=java.util.concurrent.Executors.newVirtualThreadPerTaskExecutor()){var gate=new java.util.concurrent.CountDownLatch(1);var a=pool.submit(()->{gate.await();try{evidence.record(o.id(),alloc);return 200;}catch(OrderProblem ex){return ex.status();}});var c=pool.submit(()->{gate.await();try{orders.cancel(o.id(),new Cancellation(version,"cancel remainder","cancel",o.lines().getFirst().id(),6));return 200;}catch(OrderProblem ex){return ex.status();}});gate.countDown();assertEquals(Set.of(200,409),Set.of(a.get(),c.get()));var line=orders.get(o.id()).lines().getFirst();assertEquals(10,line.cancelled()+line.shipped()+line.remaining());}}
 @Test void deliveryCannotOvercountOneReferencedShipment(){var o=order("PHYSICAL");record(o,"ALLOCATION",4,"allocation",null,null);record(o,"SHIPMENT",4,"shipment","allocation",null);record(o,"DELIVERY",3,"delivery-one",null,"shipment");assertEquals("CONFLICT",record(o,"DELIVERY",2,"delivery-two",null,"shipment").status());assertEquals(3,orders.get(o.id()).lines().getFirst().delivered());}
 @Test void unknownInFlightOperationBlocksCancellation(){var o=order("PHYSICAL");String task=db.queryForObject("SELECT id FROM order_tasks WHERE order_id=? AND kind='ALLOCATION'",String.class,o.id());var lease=execution.claim(task,"worker",java.time.Duration.ofSeconds(30)).orElseThrow();execution.dispatch(lease);execution.recordUnknown(lease,"provider timed out");assertEquals(409,assertThrows(OrderProblem.class,()->orders.cancel(o.id(),new Cancellation(orders.get(o.id()).version(),"cancel","cancel",o.lines().getFirst().id(),2))).status());}

 @Test void unreconciledPendingDeliveryBlocksCancellation(){var o=order("PHYSICAL");record(o,"DELIVERY",4,"early-delivery",null,"unseen-shipment");assertEquals(409,assertThrows(OrderProblem.class,()->orders.cancel(o.id(),new Cancellation(orders.get(o.id()).version(),"cancel everything","cancel",o.lines().getFirst().id(),10))).status());}

 @Test void allocationRequiresExplicitFutureExpiry(){var o=order("PHYSICAL");var command=new EvidenceCommand(orders.get(o.id()).version(),"missing-expiry","verified",o.lines().getFirst().id(),"ALLOCATION",4,"allocation",Instant.now(),null,null,null);assertEquals(422,assertThrows(OrderProblem.class,()->evidence.record(o.id(),command)).status());assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM allocation_lots",Integer.class));assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM fulfillment_evidence",Integer.class));}

 @Test void newlyRecordedAllocationRejectsExpiredTimestamp(){var o=order("PHYSICAL");var command=command(o,"ALLOCATION",4,"expired-allocation",null,null,Instant.now().minusSeconds(60),Instant.now().minusSeconds(10));assertEquals(422,assertThrows(OrderProblem.class,()->evidence.record(o.id(),command)).status());assertEquals(0,db.queryForObject("SELECT COUNT(*) FROM allocation_lots",Integer.class));}
}
